package com.example.Hospital.Management.System.repositories; import com.example.Hospital.Management.System.entities.Admission; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface AdmissionRepository extends JpaRepository<Admission,Long>{List<Admission> findByIsActiveTrue(); long countByRoomIdAndDischargeDateIsNullAndIsActiveTrue(Long id); @Query("select a from Admission a where a.room.floor=:floor and a.isActive=true and a.dischargeDate is null") List<Admission> activeOnFloor(@Param("floor") Integer floor);}
